static int[] countWork(int n) {
    n = Math.max(0, n);
    int linear = 0;
    for (int i = 0; i < n; i++) linear++;

    int pairs = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) pairs++;
    }

    int doubling = 0;
    int size = 1;
    while (size < n) {
        doubling++;
        if (size > n / 2) break;
        size *= 2;
    }
    return new int[]{linear, pairs, doubling};
}
